/****************************************************************************
 * vibrate.c — 振动马达驱动（PWM）
 *
 * 通过 PWM 控制振动马达，支持多种振动模式
 * PWM 频率：200Hz
 * 占空比 = intensity / 100
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <nuttx/timers/pwm.h>
#include <pthread.h>

#include "vibrate.h"

/****************************************************************************
 * 内部状态
 ****************************************************************************/

static int      g_fd      = -1;      /* PWM 设备文件描述符 */
static uint8_t  g_channel = 0;       /* PWM 通道 */
static volatile int g_running = 0;   /* 异步振动运行标志 */

/****************************************************************************
 * PWM 频率
 ****************************************************************************/

#define VIBRATE_FREQ_HZ   200

/****************************************************************************
 * 振动时序参数（毫秒）
 ****************************************************************************/

#define SHORT_MS          150
#define LONG_MS           800
#define TRIPLE_GAP_MS     150
#define STRONG_ROUND_GAP  800

/****************************************************************************
 * 内部函数：设置 PWM 占空比
 ****************************************************************************/

static int pwm_set_duty(uint8_t intensity)
{
  if (g_fd < 0)
    return -1;

  /* intensity 0-100 → duty 0-65535 */

  uint32_t duty = (uint32_t)intensity * 65535 / 100;

  struct pwm_info_s info;
  memset(&info, 0, sizeof(info));
  info.frequency = VIBRATE_FREQ_HZ;
  info.duty      = duty;

  int ret = ioctl(g_fd, PWMIOC_SETCHARACTERISTICS,
                  (unsigned long)&info);
  if (ret < 0)
    {
      printf("[vibrate] PWM set characteristics failed: %d\n", ret);
      return -1;
    }

  return 0;
}

/****************************************************************************
 * 内部函数：启动 / 停止 PWM
 ****************************************************************************/

static int pwm_start(void)
{
  if (g_fd < 0) return -1;
  return ioctl(g_fd, PWMIOC_START, 0);
}

static int pwm_stop(void)
{
  if (g_fd < 0) return -1;
  return ioctl(g_fd, PWMIOC_STOP, 0);
}

/****************************************************************************
 * 内部函数：振动指定时长（毫秒）
 ****************************************************************************/

static void vibrate_ms(uint32_t ms, uint8_t intensity)
{
  pwm_set_duty(intensity);
  pwm_start();
  usleep(ms * 1000);
  pwm_stop();
  usleep(1000); /* 短暂停顿，确保马达完全停止 */
}

/****************************************************************************
 * 公共 API
 ****************************************************************************/

int vibrate_init(const char *pwm_name, uint8_t channel)
{
  if (g_fd >= 0)
    {
      printf("[vibrate] Already initialized\n");
      return 0;
    }

  g_fd = open(pwm_name, O_RDONLY);
  if (g_fd < 0)
    {
      printf("[vibrate] Cannot open %s\n", pwm_name);
      return -1;
    }

  g_channel = channel;

  /* 确保初始状态为停止 */

  pwm_stop();

  printf("[vibrate] Init OK: %s ch%d\n", pwm_name, channel);
  return 0;
}

int vibrate_start(uint8_t intensity)
{
  if (intensity > 100) intensity = 100;
  if (intensity == 0) return vibrate_stop();

  return pwm_set_duty(intensity) || pwm_start();
}

int vibrate_stop(void)
{
  return pwm_stop();
}

int vibrate_pattern(vibrate_mode_t mode, uint8_t intensity)
{
  if (g_fd < 0)
    {
      printf("[vibrate] Not initialized\n");
      return -1;
    }

  if (intensity > 100) intensity = 100;
  if (intensity == 0) return 0;

  switch (mode)
    {
      case VIBRATE_SHORT:
        vibrate_ms(SHORT_MS, intensity);
        break;

      case VIBRATE_LONG:
        vibrate_ms(LONG_MS, intensity);
        break;

      case VIBRATE_TRIPLE_SHORT:
        for (int i = 0; i < 3; i++)
          {
            vibrate_ms(SHORT_MS, intensity);
            if (i < 2) usleep(TRIPLE_GAP_MS * 1000);
          }
        break;

      case VIBRATE_STRONG:
        /* 第一轮三短震 */

        for (int i = 0; i < 3; i++)
          {
            vibrate_ms(SHORT_MS, intensity);
            if (i < 2) usleep(TRIPLE_GAP_MS * 1000);
          }

        usleep(STRONG_ROUND_GAP * 1000);

        /* 第二轮三短震 */

        for (int i = 0; i < 3; i++)
          {
            vibrate_ms(SHORT_MS, intensity);
            if (i < 2) usleep(TRIPLE_GAP_MS * 1000);
          }
        break;

      default:
        printf("[vibrate] Unknown mode: %d\n", mode);
        return -1;
    }

  return 0;
}

/****************************************************************************
 * 异步振动线程
 ****************************************************************************/

typedef struct {
  vibrate_mode_t mode;
  uint8_t        intensity;
} async_arg_t;

static void *async_thread(void *arg)
{
  async_arg_t *a = (async_arg_t *)arg;
  vibrate_pattern(a->mode, a->intensity);
  g_running = 0;
  free(a);
  return NULL;
}

int vibrate_pattern_async(vibrate_mode_t mode, uint8_t intensity)
{
  if (g_running)
    {
      printf("[vibrate] Async pattern already running\n");
      return -1;
    }

  async_arg_t *arg = malloc(sizeof(async_arg_t));
  if (!arg) return -1;

  arg->mode      = mode;
  arg->intensity = intensity;
  g_running = 1;

  pthread_t tid;
  int ret = pthread_create(&tid, NULL, async_thread, arg);
  if (ret != 0)
    {
      printf("[vibrate] pthread_create failed: %d\n", ret);
      g_running = 0;
      free(arg);
      return -1;
    }

  pthread_detach(tid);
  return 0;
}

void vibrate_deinit(void)
{
  if (g_fd >= 0)
    {
      pwm_stop();
      close(g_fd);
      g_fd = -1;
      printf("[vibrate] Deinitialized\n");
    }
}

/****************************************************************************
 * 使用示例
 ****************************************************************************/

#ifdef VIBRATE_EXAMPLE

/*
 * 编译示例：在 Kconfig 中添加 CONFIG_VIBRATE_EXAMPLE=y
 * 运行：nsh> vibrate_test
 */

int main(int argc, char *argv[])
{
  printf("=== Vibrate Test ===\n");

  /* 初始化：PWM0 通道 0 */

  if (vibrate_init("/dev/pwm0", 0) < 0)
    {
      printf("Init failed\n");
      return -1;
    }

  /* 测试短震 */

  printf("Short vibration...\n");
  vibrate_pattern(VIBRATE_SHORT, 80);
  usleep(500000);

  /* 测试长震 */

  printf("Long vibration...\n");
  vibrate_pattern(VIBRATE_LONG, 60);
  usleep(500000);

  /* 测试三短震（课程提醒） */

  printf("Triple short (course reminder)...\n");
  vibrate_pattern(VIBRATE_TRIPLE_SHORT, 80);
  usleep(500000);

  /* 测试强提醒（久坐告警） */

  printf("Strong alert (sedentary)...\n");
  vibrate_pattern(VIBRATE_STRONG, 100);
  usleep(500000);

  /* 测试异步振动 */

  printf("Async triple short...\n");
  vibrate_pattern_async(VIBRATE_TRIPLE_SHORT, 70);
  printf("Main thread continues...\n");
  usleep(2000000);

  vibrate_deinit();
  printf("Done.\n");
  return 0;
}

#endif /* VIBRATE_EXAMPLE */

