int vibrate_stop(void)
{
  return pwm_stop();
}

int vibrate_pattern(vibrate_mode_t mode, uint8_t intensity)
{
  if (g_fd < 0)
    {
      printf("[vibrate] Not initialized\n");
      return -1;
    }

  if (intensity > 100) intensity = 100;
  if (intensity == 0) return 0;

  switch (mode)
    {
      case VIBRATE_SHORT:
        vibrate_ms(SHORT_MS, intensity);
        break;

      case VIBRATE_LONG:
        vibrate_ms(LONG_MS, intensity);
        break;

      case VIBRATE_TRIPLE_SHORT:
        for (int i = 0; i < 3; i++)
          {
            vibrate_ms(SHORT_MS, intensity);
            if (i < 2) usleep(TRIPLE_GAP_MS * 1000);
          }
        break;

      case VIBRATE_STRONG:
        /* 第一轮三短震 */

        for (int i = 0; i < 3; i++)
          {
            vibrate_ms(SHORT_MS, intensity);
            if (i < 2) usleep(TRIPLE_GAP_MS * 1000);
          }

        usleep(STRONG_ROUND_GAP * 1000);

        /* 第二轮三短震 */

        for (int i = 0; i < 3; i++)
          {
            vibrate_ms(SHORT_MS, intensity);
            if (i < 2) usleep(TRIPLE_GAP_MS * 1000);
          }
        break;

      default:
        printf("[vibrate] Unknown mode: %d\n", mode);
        return -1;
    }

  return 0;
}

/****************************************************************************
 * 异步振动线程
 ****************************************************************************/

typedef struct {
  vibrate_mode_t mode;
  uint8_t        intensity;
} async_arg_t;

static void *async_thread(void *arg)
{
  async_arg_t *a = (async_arg_t *)arg;
  vibrate_pattern(a->mode, a->intensity);
  g_running = 0;
  free(a);
  return NULL;
}

int vibrate_pattern_async(vibrate_mode_t mode, uint8_t intensity)
{
  if (g_running)
    {
      printf("[vibrate] Async pattern already running\n");
      return -1;
    }

  async_arg_t *arg = malloc(sizeof(async_arg_t));
  if (!arg) return -1;

  arg->mode      = mode;
  arg->intensity = intensity;
  g_running = 1;

  pthread_t tid;
  int ret = pthread_create(&tid, NULL, async_thread, arg);
  if (ret != 0)
    {
      printf("[vibrate] pthread_create failed: %d\n", ret);
      g_running = 0;
      free(arg);
      return -1;
    }

  pthread_detach(tid);
  return 0;
}

void vibrate_deinit(void)
{
  if (g_fd >= 0)
    {
      pwm_stop();
      close(g_fd);
      g_fd = -1;
      printf("[vibrate] Deinitialized\n");
    }
}

/****************************************************************************
 * vibrate_test.c — 振动马达测试程序
 *
 * 用法：nsh> vibrate_test
 *
 * 测试所有振动模式，验证硬件是否正常
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include <stdio.h>
#include <unistd.h>
#include "vibrate.h"

/****************************************************************************
 * 主函数
 ****************************************************************************/

int main(int argc, char *argv[])
{
  printf("\n=== Vibrate Motor Test ===\n\n");

  /* 初始化：尝试 /dev/pwm0 */

  if (vibrate_init("/dev/pwm0", 0) < 0)
    {
      printf("ERROR: Cannot init vibrator on /dev/pwm0\n");
      printf("Check if PWM device exists: ls /dev/pwm*\n");
      return -1;
  }

  /* 测试 1：短震 */

  printf("[1/5] Short vibration (80%%)...\n");
  vibrate_pattern(VIBRATE_SHORT, 80);
  printf("      Did you feel it? (waiting 1s)\n\n");
  usleep(1000000);

  /* 测试 2：长震 */

  printf("[2/5] Long vibration (60%%)...\n");
  vibrate_pattern(VIBRATE_LONG, 60);
  printf("      Did you feel it? (waiting 1s)\n\n");
  usleep(1000000);

  /* 测试 3：三短震（课程提醒模式） */

  printf("[3/5] Triple short - course reminder (80%%)...\n");
  vibrate_pattern(VIBRATE_TRIPLE_SHORT, 80);
  printf("      3 pulses? (waiting 1s)\n\n");
  usleep(1000000);

  /* 测试 4：强提醒（久坐告警模式） */

  printf("[4/5] Strong alert - sedentary warning (100%%)...\n");
  vibrate_pattern(VIBRATE_STRONG, 100);
  printf("      2 rounds of 3 pulses? (waiting 1s)\n\n");
  usleep(1000000);

  /* 测试 5：异步振动 */

  printf("[5/5] Async triple short (70%%)...\n");
  vibrate_pattern_async(VIBRATE_TRIPLE_SHORT, 70);
  printf("      Main thread continues immediately...\n");
  usleep(2000000);

  /* 清理 */

  vibrate_deinit();
  printf("\n=== Test Complete ===\n\n");
  return 0;
}

