/****************************************************************************
 * vibrate.h — 振动马达驱动（GPIO）
 *
 * 硬件：黄山派 SF32LB52，振动马达接 PA20
 * 控制：GPIO 高低电平
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#ifndef __VIBRATE_H
#define __VIBRATE_H

#include <stdint.h>

/****************************************************************************
 * 振动模式
 ****************************************************************************/

typedef enum {
  VIBRATE_SHORT,        /* 短震：150ms */
  VIBRATE_LONG,         /* 长震：800ms */
  VIBRATE_TRIPLE_SHORT, /* 三短震：150ms x 3，间隔 150ms */
  VIBRATE_STRONG,       /* 强提醒：两轮三短震，中间停 800ms */
} vibrate_mode_t;

/****************************************************************************
 * 公共 API
 ****************************************************************************/

/**
 * 初始化振动马达 GPIO
 * @return 0 成功，-1 失败
 */

int vibrate_init(void);

/**
 * 启动振动（马达开）
 */

void vibrate_on(void);

/**
 * 停止振动（马达关）
 */

void vibrate_off(void);

/**
 * 按模式振动（阻塞直到完成）
 *
 * @param mode 振动模式
 * @return 0 成功，-1 失败
 */

int vibrate_pattern(vibrate_mode_t mode);

/**
 * 异步振动（后台线程执行）
 *
 * @param mode 振动模式
 * @return 0 成功，-1 失败
 */

int vibrate_pattern_async(vibrate_mode_t mode);

/**
 * 反初始化
 */

void vibrate_deinit(void);

#endif /* __VIBRATE_H */

/****************************************************************************
 * vibrate.c — 振动马达驱动（GPIO PA20）
 *
 * 通过 GPIO 控制振动马达
 * PA20 = HIGH → 马达转
 * PA20 = LOW  → 马达停
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <nuttx/ioexpander/gpio.h>
#include <pthread.h>

#include "vibrate.h"

/****************************************************************************
 * GPIO 引脚定义
 ****************************************************************************/

/* PA20 对应 GPIO 编号：
 * SF32LB52 GPIO = port * 32 + pin
 * PA20 = 0 * 32 + 20 = 20
 */

#define MOTOR_GPIO_PIN    20
#define MOTOR_GPIO_PATH   "/dev/gpio20"

/****************************************************************************
 * 内部状态
 ****************************************************************************/

static int g_fd = -1;

/****************************************************************************
 * 振动时序参数（毫秒）
 ****************************************************************************/

#define SHORT_MS          150
#define LONG_MS           800
#define TRIPLE_GAP_MS     150
#define STRONG_ROUND_GAP  800

/****************************************************************************
 * 内部函数：GPIO 控制
 ****************************************************************************/

static int gpio_set(int value)
{
  if (g_fd < 0) return -1;

  struct gpio_operation_s op;
  memset(&op, 0, sizeof(op));
  op.gp_pintype = GPIO_OUTPUT_PIN;
  op.gp_value   = value ? 1 : 0;

  return ioctl(g_fd, GPIOC_WRITE, (unsigned long)&op);
}

/****************************************************************************
 * 公共 API
 ****************************************************************************/

int vibrate_init(void)
{
  if (g_fd >= 0)
    {
      printf("[vibrate] Already initialized\n");
      return 0;
    }

  /* 打开 GPIO 设备 */

  g_fd = open(MOTOR_GPIO_PATH, O_RDWR);
  if (g_fd < 0)
    {
      printf("[vibrate] Cannot open %s, trying /dev/gpio0\n",
             MOTOR_GPIO_PATH);

      /* 备选：尝试通用 GPIO 设备 */

      g_fd = open("/dev/gpio0", O_RDWR);
      if (g_fd < 0)
        {
          printf("[vibrate] GPIO open failed\n");
          return -1;
        }
    }

  /* 配置为输出模式 */

  struct gpio_operation_s op;
  memset(&op, 0, sizeof(op));
  op.gp_pintype = GPIO_OUTPUT_PIN;
  op.gp_value   = 0;
  ioctl(g_fd, GPIOC_SETPINTYPE, (unsigned long)&op);

  /* 初始状态：关闭 */

  gpio_set(0);

  printf("[vibrate] Init OK: pin PA20\n");
  return 0;
}

void vibrate_on(void)
{
  gpio_set(1);
}

void vibrate_off(void)
{
  gpio_set(0);
}

int vibrate_pattern(vibrate_mode_t mode)
{
  if (g_fd < 0)
    {
      printf("[vibrate] Not initialized\n");
      return -1;
    }

  switch (mode)
    {
      case VIBRATE_SHORT:
        gpio_set(1);
        usleep(SHORT_MS * 1000);
        gpio_set(0);
        break;

      case VIBRATE_LONG:
        gpio_set(1);
        usleep(LONG_MS * 1000);
        gpio_set(0);
        break;

      case VIBRATE_TRIPLE_SHORT:
        for (int i = 0; i < 3; i++)
          {
            gpio_set(1);
            usleep(SHORT_MS * 1000);
            gpio_set(0);
            if (i < 2) usleep(TRIPLE_GAP_MS * 1000);
          }
        break;

      case VIBRATE_STRONG:
        for (int i = 0; i < 3; i++)
          {
            gpio_set(1);
            usleep(SHORT_MS * 1000);
            gpio_set(0);
            if (i < 2) usleep(TRIPLE_GAP_MS * 1000);
          }
        usleep(STRONG_ROUND_GAP * 1000);
        for (int i = 0; i < 3; i++)
          {
            gpio_set(1);
            usleep(SHORT_MS * 1000);
            gpio_set(0);
            if (i < 2) usleep(TRIPLE_GAP_MS * 1000);
          }
        break;

      default:
        return -1;
    }

  /* 确保最终停止 */

  gpio_set(0);
  return 0;
}

/****************************************************************************
 * 异步振动
 ****************************************************************************/

static volatile int g_async_running = 0;

static void *async_thread(void *arg)
{
  vibrate_mode_t mode = (vibrate_mode_t)(int)arg;
  vibrate_pattern(mode);
  g_async_running = 0;
  return NULL;
}

int vibrate_pattern_async(vibrate_mode_t mode)
{
  if (g_async_running) return -1;

  g_async_running = 1;
  pthread_t tid;
  int ret = pthread_create(&tid, NULL, async_thread,
                           (void *)(int)mode);
  if (ret != 0)
    {
      g_async_running = 0;
      return -1;
    }

  pthread_detach(tid);
  return 0;
}

void vibrate_deinit(void)
{
  if (g_fd >= 0)
    {
      gpio_set(0);
      close(g_fd);
      g_fd = -1;
      printf("[vibrate] Deinitialized\n");
    }
}

