/****************************************************************************
 * vibrate.c — 振动马达驱动（GPIO PA20）
 *
 * 通过 GPIO 控制振动马达
 * PA20 = HIGH → 马达转
 * PA20 = LOW  → 马达停
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <nuttx/ioexpander/gpio.h>
#include <pthread.h>

#include "vibrate.h"

/****************************************************************************
 * GPIO 引脚定义
 ****************************************************************************/

#define MOTOR_GPIO_PATH   "/dev/gpio20"

/****************************************************************************
 * 内部状态
 ****************************************************************************/

static int g_fd = -1;

/****************************************************************************
 * 振动时序参数（毫秒）
 ****************************************************************************/

#define SHORT_MS          150
#define LONG_MS           800
#define TRIPLE_GAP_MS     150
#define STRONG_ROUND_GAP  800

/****************************************************************************
 * 内部函数：GPIO 控制
 ****************************************************************************/

static int gpio_write(int value)
{
  if (g_fd < 0) return -1;
  return ioctl(g_fd, GPIOC_WRITE, (unsigned long)(value ? 1 : 0));
}

/****************************************************************************
 * 公共 API
 ****************************************************************************/

int vibrate_init(void)
{
  if (g_fd >= 0)
    {
      printf("[vibrate] Already initialized\n");
      return 0;
    }

  g_fd = open(MOTOR_GPIO_PATH, O_RDWR);
  if (g_fd < 0)
    {
      printf("[vibrate] Cannot open %s\n", MOTOR_GPIO_PATH);
      return -1;
    }

  /* 配置为输出模式 */

  ioctl(g_fd, GPIOC_SETPINTYPE, GPIO_OUTPUT_PIN);

  /* 初始状态：关闭 */

  gpio_write(0);

  printf("[vibrate] Init OK: PA20\n");
  return 0;
}

void vibrate_on(void)
{
  gpio_write(1);
}

void vibrate_off(void)
{
  gpio_write(0);
}

int vibrate_pattern(vibrate_mode_t mode)
{
  if (g_fd < 0)
    {
      printf("[vibrate] Not initialized\n");
      return -1;
    }

  switch (mode)
    {
      case VIBRATE_SHORT:
        gpio_write(1);
        usleep(SHORT_MS * 1000);
        gpio_write(0);
        break;

      case VIBRATE_LONG:
        gpio_write(1);
        usleep(LONG_MS * 1000);
        gpio_write(0);
        break;

      case VIBRATE_TRIPLE_SHORT:
        for (int i = 0; i < 3; i++)
          {
            gpio_write(1);
            usleep(SHORT_MS * 1000);
            gpio_write(0);
            if (i < 2) usleep(TRIPLE_GAP_MS * 1000);
          }
        break;

      case VIBRATE_STRONG:
        for (int i = 0; i < 3; i++)
          {
            gpio_write(1);
            usleep(SHORT_MS * 1000);
            gpio_write(0);
            if (i < 2) usleep(TRIPLE_GAP_MS * 1000);
          }
        usleep(STRONG_ROUND_GAP * 1000);
        for (int i = 0; i < 3; i++)
          {
            gpio_write(1);
            usleep(SHORT_MS * 1000);
            gpio_write(0);
            if (i < 2) usleep(TRIPLE_GAP_MS * 1000);
          }
        break;

      default:
        return -1;
    }

  gpio_write(0);
  return 0;
}

/****************************************************************************
 * 异步振动
 ****************************************************************************/

static volatile int g_async_running = 0;

static void *async_thread(void *arg)
{
  vibrate_mode_t mode = (vibrate_mode_t)(int)arg;
  vibrate_pattern(mode);
  g_async_running = 0;
  return NULL;
}

int vibrate_pattern_async(vibrate_mode_t mode)
{
  if (g_async_running) return -1;

  g_async_running = 1;
  pthread_t tid;
  int ret = pthread_create(&tid, NULL, async_thread,
                           (void *)(int)mode);
  if (ret != 0)
    {
      g_async_running = 0;
      return -1;
    }

  pthread_detach(tid);
  return 0;
}

void vibrate_deinit(void)
{
  if (g_fd >= 0)
    {
      gpio_write(0);
      close(g_fd);
      g_fd = -1;
      printf("[vibrate] Deinitialized\n");
    }
}

