/****************************************************************************
 * vibrate.c — 振动马达驱动（PA20 PWM + LDO3 电源）
 *
 * 硬件连接：
 *   VIB+ = LDO3 输出 VDD33_VOUT (3.3V)
 *   VIB- = PA20 PWM 控制 MOS 管
 *
 * 驱动流程：
 *   1. HAL_PMU_ConfigPeriLdo() 开启 LDO3 电源
 *   2. HAL_PIN_Set() 配置 PA20 为 GPTIM 功能
 *   3. HAL_GPT_PWM_Init() 初始化 PWM
 *   4. 修改 CCR (Pulse) 值改变占空比 → 控制震动强度
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <unistd.h>

/* SiFli HAL 头文件 */

#include "bf0_hal.h"
#include "bf0_hal_pmu.h"
#include "bf0_hal_tim.h"
#include "bf0_hal_pinmux.h"

#include "vibrate.h"

/****************************************************************************
 * 硬件配置
 ****************************************************************************/

/* PA20 对应 GPTIM2_CH1（根据 SF32LB52 引脚复用表） */

#define MOTOR_TIM           GPTIM2           /* 定时器实例 */
#define MOTOR_TIM_CH        TIM_CHANNEL_1    /* 通道 1 */
#define MOTOR_PIN           PAD_PA20         /* 引脚 PA20 */
#define MOTOR_PIN_FUNC      GPTIM2_CH1       /* 引脚功能 */

/* PWM 参数 */

#define PWM_FREQ_HZ         200              /* PWM 频率 200Hz */
#define PWM_PERIOD_US        (1000000 / PWM_FREQ_HZ)  /* 周期 5000us */

/* HAL 定时器句柄（静态分配） */

static GPT_HandleTypeDef g_htim;
static int g_initialized = 0;

/****************************************************************************
 * 内部函数：计算 Pulse 值
 *
 * Pulse = (Period + 1) * strength / 100
 * Period = TIM_CLK / (PSC + 1) / PWM_FREQ - 1
 ****************************************************************************/

static uint32_t calc_pulse(uint8_t strength)
{
  if (strength > 100) strength = 100;

  /* Period 值从 Init 结构体获取 */

  uint32_t period = g_htim.Init.Period;
  return (period + 1) * strength / 100;
}

/****************************************************************************
 * 公共 API：初始化
 ****************************************************************************/

int vibrate_init(void)
{
  if (g_initialized)
    {
      printf("[vibrate] Already initialized\n");
      return 0;
    }

  printf("[vibrate] Init start...\n");

  /* ===== Step 1: 开启 PMU LDO3 电源 (3.3V) ===== */

  printf("[vibrate] Enabling PMU LDO3...\n");
  HAL_PMU_ConfigPeriLdo(PMU_PERI_LDO3_3V3, true, true);
  printf("[vibrate] LDO3 enabled\n");

  /* ===== Step 2: 配置 PA20 引脚为 GPTIM2_CH1 功能 ===== */

  printf("[vibrate] Configuring PA20 as GPTIM2_CH1...\n");
  HAL_PIN_Set(MOTOR_PIN, MOTOR_PIN_FUNC, PIN_NOPULL, 1);

  /* ===== Step 3: 配置 GPTIM2 为 PWM 模式 ===== */

  printf("[vibrate] Initializing GPTIM2 PWM...\n");

  /* 定时器基本配置：
   * - 时钟分频：假设 TIM_CLK = 24MHz
   * - PSC = 24-1 → 计数频率 = 24MHz / 24 = 1MHz
   * - Period = 1MHz / 200Hz - 1 = 4999
   * - PWM 周期 = 5000us = 5ms (200Hz)
   */

  memset(&g_htim, 0, sizeof(g_htim));
  g_htim.Instance         = MOTOR_TIM;
  g_htim.Init.Prescaler   = 24 - 1;        /* 分频系数 */
  g_htim.Init.Period      = 5000 - 1;      /* 自动重装载值 */
  g_htim.Init.ClockDivision = TIM_CLOCKDIVISION_DIV1;
  g_htim.Init.CounterMode  = TIM_COUNTERMODE_UP;
  g_htim.Init.RepetitionCounter = 0;
  g_htim.Init.AutoReloadPreload = TIM_AUTORELOAD_PRELOAD_ENABLE;

  if (HAL_GPT_PWM_Init(&g_htim) != HAL_OK)
    {
      printf("[vibrate] ERROR: PWM init failed\n");
      return -1;
    }

  /* ===== Step 4: 配置 PWM 通道 ===== */

  GPT_OC_InitTypeDef oc_config;
  memset(&oc_config, 0, sizeof(oc_config));
  oc_config.OCMode     = GPT_OCMODE_PWM1;   /* PWM 模式 1 */
  oc_config.Pulse      = 0;                  /* 初始占空比 = 0 */
  oc_config.OCPolarity = TIM_OCPOLARITY_HIGH;
  oc_config.OCFastMode = TIM_OCFAST_DISABLE;

  if (HAL_GPT_PWM_ConfigChannel(&g_htim, &oc_config, MOTOR_TIM_CH) != HAL_OK)
    {
      printf("[vibrate] ERROR: PWM channel config failed\n");
      return -1;
    }

  /* ===== Step 5: 启动 PWM 输出 ===== */

  if (HAL_GPT_PWM_Start(&g_htim, MOTOR_TIM_CH) != HAL_OK)
    {
      printf("[vibrate] ERROR: PWM start failed\n");
      return -1;
    }

  g_initialized = 1;
  printf("[vibrate] Init OK: PA20 PWM @ %dHz\n", PWM_FREQ_HZ);
  return 0;
}

/****************************************************************************
 * 公共 API：设置震动强度
 ****************************************************************************/

void vibrate_set_strength(uint8_t strength)
{
  if (!g_initialized) return;
  if (strength > 100) strength = 100;

  uint32_t pulse = calc_pulse(strength);

  /* 修改 CCR（Capture Compare Register）改变占空比 */

  __HAL_TIM_SET_COMPARE(&g_htim, MOTOR_TIM_CH, pulse);
}

/****************************************************************************
 * 公共 API：震动指定时长
 ****************************************************************************/

void vibrate_pulse(uint32_t ms, uint8_t strength)
{
  if (!g_initialized) return;

  vibrate_set_strength(strength);
  usleep(ms * 1000);
  vibrate_set_strength(0);
}

/****************************************************************************
 * 公共 API：停止震动
 ****************************************************************************/

void vibrate_stop(void)
{
  vibrate_set_strength(0);
}

/****************************************************************************
 * 公共 API：反初始化
 ****************************************************************************/

void vibrate_deinit(void)
{
  if (!g_initialized) return;

  /* 停止 PWM */

  HAL_GPT_PWM_Stop(&g_htim, MOTOR_TIM_CH);

  /* 关闭定时器 */

  HAL_GPT_DeInit(&g_htim);

  /* 关闭 LDO3 电源 */

  HAL_PMU_ConfigPeriLdo(PMU_PERI_LDO3_3V3, false, false);

  g_initialized = 0;
  printf("[vibrate] Deinitialized\n");
}

/****************************************************************************
 * 测试函数：上电测试
 ****************************************************************************/

void vibrate_test_poweron(void)
{
  printf("[vibrate] Power-on test:\n");
  printf("  Strong 300ms -> Stop 200ms -> Weak 300ms\n");

  /* 强震 300ms (强度 100) */

  printf("  [1] Strong 300ms...\n");
  vibrate_pulse(300, 100);

  /* 停 200ms */

  usleep(200000);

  /* 弱震 300ms (强度 30) */

  printf("  [2] Weak 300ms...\n");
  vibrate_pulse(300, 30);

  printf("  Done.\n");
}

